// Generated by tooling/unicode-cases/regexp.ts; Node 24.20.0, Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, The design and Staying identical to node.
// Context: lone high and low surrogates differ from a valid pair when matching one character.
const pattern0 = /^.$/;
const pattern1 = /^.$/u;
const pattern2 = /^.$/v;
const samples: [string, boolean, boolean, boolean][] = [
  ["\ud800", true, true, true],
  ["\udc00", true, true, true],
  ["\ud800\udc00", false, true, true],
  ["\udc00\ud800", false, false, false],
  ["\ud800\u0041", false, false, false],
  ["\ud83d\ude00", false, true, true],
  ["\u0041", true, true, true],
];
for (const sample of samples) {
  assert.sameValue(pattern0.test(sample[0]), sample[1], "surrogate-unit-boundaries pattern 0");
  assert.sameValue(pattern1.test(sample[0]), sample[2], "surrogate-unit-boundaries pattern 1");
  assert.sameValue(pattern2.test(sample[0]), sample[3], "surrogate-unit-boundaries pattern 2");
}
